const searchPlaceholders: Record<string, string> = { orders: "搜索订单号、客户、邮箱或状态", invoices: "搜索发票、订单、客户或抬头", support: "搜索工单、主题、客户、订单或售后单", payments: "搜索交易号、订单号或客户", members: "搜索会员姓名、邮箱或手机号", products: "搜索商品名称、分类或状态", community: "搜索作者、标题、正文或审核状态", reviews: "搜索商品、评价人或内容", returns: "搜索售后单、订单号或客户邮箱", partnerships: "搜索申请人、公司、城市或合作类型", marketing: "搜索优惠码、礼品卡或订单号", subscribers: "搜索订阅邮箱或状态", notifications: "搜索任务、模板或接收人" };

export function AdminClient({ viewer, canSignOut }: { viewer: AdminViewer; canSignOut: boolean }) {
  const defaultTab = viewer.role === "customer_service" ? "support" : viewer.role === "warehouse" ? "orders" : "overview";
  const [tab, setTab] = useState(defaultTab);
  const [data, setData] = useState<AdminData | null>(null);
  const [editing, setEditing] = useState<AdminProduct | null>(null);
  const [creating, setCreating] = useState(false);
  const [importing, setImporting] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState<AdminOrder | null>(null);
  const [selectedMember, setSelectedMember] = useState<AdminMember | null>(null);
  const [refundPayment, setRefundPayment] = useState<AdminPayment | null>(null);
  const [supportFocus, setSupportFocus] = useState("");
  const [query, setQuery] = useState("");
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(true);
  const [contentDirty, setContentDirty] = useState(false);
  const can = (permission: AdminPermission) => viewer.permissions.includes(permission);

  useEffect(() => {
    if (message !== "已保存") return;
    const timeout = window.setTimeout(() => setMessage(""), 3_000);
    return () => window.clearTimeout(timeout);
  }, [message]);

  const load = useCallback(async (view: string, options: { silent?: boolean; preserveMessage?: boolean } = {}) => {
    const silent = Boolean(options.silent);
    if (!silent) setLoading(true);
    const controller = new AbortController();
    const timeout = window.setTimeout(() => controller.abort(), 20_000);
    try {
      const response = await fetch(`/api/admin?view=${encodeURIComponent(view)}`, { cache: "no-store", signal: controller.signal });
      const body = await response.json().catch(() => ({}));
      if (!response.ok) setMessage(body.error || "加载失败，请稍后重试");
      else { setData(body); if (!options.preserveMessage) setMessage(""); }
    } catch (error) {
      setMessage(error instanceof DOMException && error.name === "AbortError" ? "读取商城数据超时，请刷新页面重试" : "无法连接商城数据，请刷新页面重试");
    } finally {
      window.clearTimeout(timeout);
      if (!silent) setLoading(false);
    }
  }, []);
  useEffect(() => { queueMicrotask(() => { void load(defaultTab); }); }, [defaultTab, load]);
  async function act(payload: Record<string, unknown>) {
    setMessage("正在保存…");
    try {
      const response = await fetch("/api/admin", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(payload) });
      const body = await response.json().catch(() => ({}));
      if (!response.ok) { setMessage(body.error || "保存失败"); return false; }
      setMessage("已保存");
      await load(tab, { silent: true, preserveMessage: true });
      return true;
    } catch {
      setMessage("无法连接后台，请检查网络后重试");
      return false;
    }
  }
  async function saveProduct(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const payload = Object.fromEntries(new FormData(event.currentTarget).entries());
    const inventoryOnly = Boolean(editing && !can("products.manage") && can("products.inventory.manage"));
    const ok = await act({ action: inventoryOnly ? "update-product-inventory" : editing ? "update-product" : "create-product", id: editing?.id, ...payload });
    if (ok) { setEditing(null); setCreating(false); }
  }
  async function saveCoupon(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const payload = Object.fromEntries(new FormData(event.currentTarget).entries());
    if (await act({ action: "create-coupon", ...payload })) event.currentTarget.reset();
  }
  async function openLinkedSupport(input: { orderId?: string; returnId?: string }) {
    setMessage("正在打开关联邮件工单…");
    const response = await fetch("/api/admin", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "open-linked-support-thread", ...input }) });
    const body = await response.json();
    if (!response.ok || !body.threadId) { setMessage(body.error || "无法打开邮件工单"); return; }
    await load("support");
    setSupportFocus(String(body.threadId));
    setSelectedOrder(null);
    setQuery("");
    setTab("support");
    setMessage("已打开关联邮件工单，可直接回复客户");
  }
  function changeTab(next: string) {
    if (tab === "content" && next !== tab && contentDirty && !window.confirm("当前内容还有未保存修改，确定离开吗？")) return;
    setContentDirty(false);
    setTab(next);
    setQuery("");
    if (next !== "support") setSupportFocus("");
    void load(next);
  }

  const normalized = query.trim().toLowerCase();
  const filtered = useMemo(() => {
    if (!data || !normalized) return { products: data?.products ?? [], orders: data?.orders ?? [], invoices: data?.invoices ?? [], members: data?.members ?? [], subscribers: data?.subscribers ?? [], returns: data?.returns ?? [], retailPartnerships: data?.retailPartnerships ?? [], coupons: data?.coupons ?? [], giftCards: data?.giftCards ?? [], payments: data?.payments ?? [], refunds: data?.refunds ?? [], notificationJobs: data?.notificationJobs ?? [], reviews: data?.reviews ?? [], communityPosts: data?.communityPosts ?? [] };
    return {
      products: data.products.filter((item) => `${item.name} ${item.slug} ${item.category} ${item.status}`.toLowerCase().includes(normalized)),
      orders: data.orders.filter((item) => `${item.id} ${item.customer} ${item.email} ${item.phone} ${item.status}`.toLowerCase().includes(normalized)),
      invoices: data.invoices.filter((item) => `${item.id} ${item.order_id} ${item.customer} ${item.customer_email} ${item.title} ${item.tax_number} ${item.status}`.toLowerCase().includes(normalized)),
      members: data.members.filter((item) => `${item.name} ${item.email} ${item.phone} ${item.status}`.toLowerCase().includes(normalized)),
      subscribers: data.subscribers.filter((item) => `${item.email} ${item.source} ${item.status}`.toLowerCase().includes(normalized)),
      returns: data.returns.filter((item) => `${item.id} ${item.order_id} ${item.email} ${item.reason} ${item.status}`.toLowerCase().includes(normalized)),
      retailPartnerships: data.retailPartnerships.filter((item) => `${item.id} ${item.contact_name} ${item.phone} ${item.company} ${item.city} ${item.cooperation_type} ${item.wechat} ${item.email} ${item.proposal} ${item.status}`.toLowerCase().includes(normalized)),
      coupons: data.coupons.filter((item) => `${item.code} ${item.kind} ${item.status}`.toLowerCase().includes(normalized)),
      giftCards: data.giftCards.filter((item) => `${item.code} ${item.order_id} ${item.recipient_name} ${item.recipient_email} ${item.status}`.toLowerCase().includes(normalized)),
      payments: data.payments.filter((item) => `${item.id} ${item.order_id} ${item.merchant_trade_no} ${item.customer} ${item.email} ${item.provider} ${item.status}`.toLowerCase().includes(normalized)),
      refunds: data.refunds.filter((item) => `${item.id} ${item.order_id} ${item.merchant_refund_no} ${item.provider} ${item.reason} ${item.status}`.toLowerCase().includes(normalized)),
      notificationJobs: data.notificationJobs.filter((item) => `${item.id} ${item.event_key} ${item.entity_id} ${item.template_key} ${item.channel} ${item.recipient} ${item.status}`.toLowerCase().includes(normalized)),
      reviews: data.reviews.filter((item) => `${item.product_slug} ${item.reviewer_name} ${item.title} ${item.body} ${item.status}`.toLowerCase().includes(normalized)),
      communityPosts: data.communityPosts.filter((item) => `${item.id} ${item.author_name} ${item.author_public_id} ${item.title} ${item.body} ${item.status} ${item.moderation_note}`.toLowerCase().includes(normalized)),
    };
  }, [data, normalized]);

  const tabMeta = adminTabMeta[tab];
  const messageIsError = /失败|无法|超时|错误/.test(message);
  return <main className="admin-shell">
    <aside className="admin-sidebar"><div className="admin-sidebar-brand"><a className="admin-brand" href="/">PUSY.CN</a><span>ADMIN</span></div><p>中国区商城管理后台</p><nav aria-label="后台功能导航">{adminNavGroups.map((group) => { const items = group.items.filter(([key]) => can(tabPermissions[key])); return items.length ? <section className="admin-nav-group" key={group.label}><b>{group.label}</b>{items.map(([key,label,icon]) => <button className={tab === key ? "active" : ""} aria-current={tab === key ? "page" : undefined} onClick={() => changeTab(key)} key={key}><i aria-hidden="true">{icon}</i><span>{label}</span>{key === "support" && Boolean(data?.stats?.unread_support) && <em className="admin-nav-count">{data?.stats?.unread_support}</em>}</button>)}</section> : null; })}</nav><div className="admin-viewer"><i>{viewer.displayName.slice(0, 1).toUpperCase()}</i><span><small>{adminRoleLabels[viewer.role]}</small><b>{viewer.displayName}</b></span>{canSignOut && <a href="/admin/logout">退出</a>}</div><a className="admin-store-link" href="/">查看商城 <span>↗</span></a></aside>
    <section className="admin-main"><header><div><p>{tabMeta.eyebrow} / PUSY.CN</p><h1>{tabMeta.title}</h1><span>{tabMeta.description}</span></div></header>
      {!['overview','analytics','settings','content','admins','audit'].includes(tab) && <div className="admin-search"><i aria-hidden="true">⌕</i><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={searchPlaceholders[tab] ?? "搜索当前列表"} aria-label="搜索当前列表" /><span>{query ? `${tab === "support" ? data?.supportThreads.filter((item) => `${item.id} ${item.subject} ${item.customer_email} ${item.customer_phone ?? ""} ${item.customer_wechat ?? ""} ${item.order_id ?? ""} ${item.return_id ?? ""}`.toLowerCase().includes(normalized)).length : tab === "orders" ? filtered.orders.length : tab === "invoices" ? filtered.invoices.length : tab === "payments" ? filtered.payments.length + filtered.refunds.length : tab === "notifications" ? filtered.notificationJobs.length : tab === "members" ? filtered.members.length : tab === "products" ? filtered.products.length : tab === "community" ? filtered.communityPosts.length : tab === "reviews" ? filtered.reviews.length : tab === "returns" ? filtered.returns.length : tab === "partnerships" ? filtered.retailPartnerships.length : tab === "marketing" ? filtered.coupons.length + filtered.giftCards.length : filtered.subscribers.length} 条结果` : ""}</span></div>}
      {message && <div className={`admin-message ${messageIsError ? "error" : ""}`} role={messageIsError ? "alert" : "status"} aria-live={messageIsError ? "assertive" : "polite"} aria-atomic="true">{message}</div>}
      {loading ? <div className="admin-loading"><i /><b>正在读取商城数据</b><span>正在同步当前模块的数据…</span></div> : data && <>
        {tab === "overview" && <div className="admin-overview"><section className="stat-grid"><article><span>累计订单</span><b>{data.stats?.order_count ?? 0}</b></article><article><span>累计销售额</span><b>{formatCnyFromRub(data.stats?.revenue ?? 0)}</b></article><article><span>平均客单价</span><b>{formatCnyFromRub(Math.round(data.stats?.avg_order_value ?? 0))}</b></article><article><span>待处理订单</span><b>{data.stats?.pending_count ?? 0}</b></article><article><span>待核验库存</span><b>{data.stats?.unverified_inventory_count ?? 0}</b></article><article><span>低库存商品</span><b>{data.stats?.low_stock_count ?? 0}</b></article><article><span>待审核售后</span><b>{data.stats?.pending_returns ?? 0}</b></article><article><span>待联系合作</span><b>{data.stats?.pending_partnerships ?? 0}</b></article></section><RevenueChart points={data.revenueTrend} /><section className="admin-panel"><div className="admin-panel-title"><h2>最新订单</h2><button onClick={() => changeTab("orders")}>查看全部</button></div><OrderTable orders={data.orders.slice(0, 6)} canManage={can("orders.manage")} canSupport={can("support.manage")} onOpen={setSelectedOrder} onSupport={(orderId) => void openLinkedSupport({ orderId })} onStatus={(id,status) => act({ action:"update-order-status", id, status })} /></section></div>}
        {tab === "analytics" && <AnalyticsAdmin analytics={data.analytics} />}
        {tab === "growth" && <GrowthAdmin data={data.growth} onAct={act} />}
        {tab === "content" && <ContentAdmin key={data.contentRevisions.find((item) => item.status === "published")?.id ?? "content"} content={data.content} revisions={data.contentRevisions} onAct={act} onDirtyChange={setContentDirty} />}
        {tab === "settings" && <ChinaRegionAdmin settings={data.region} providers={data.providers} onOpenPayments={() => changeTab("payments")} />}
        {tab === "orders" && <OrderManagement orders={filtered.orders} shipments={data.shipments} shipmentEvents={data.shipmentEvents} canManage={can("orders.manage") || can("orders.fulfill")} canFullManage={can("orders.manage")} canSupport={can("support.manage")} onOpen={setSelectedOrder} onSupport={(orderId) => void openLinkedSupport({ orderId })} onStatus={(id,status) => act({ action:"update-order-status", id, status })} onAct={act} />}
        {tab === "invoices" && <InvoiceAdmin invoices={filtered.invoices} onAct={act} />}
        {tab === "support" && <SupportAdmin key={supportFocus || "support"} threads={data.supportThreads} messages={data.supportMessages} returnEvents={data.returnEvents} cannedReplies={data.cannedReplies} receiving={data.supportReceiving} agents={data.supportAgents} customerOrders={data.supportCustomerOrders} customerReturns={data.supportCustomerReturns} query={query} viewer={viewer} focusThreadId={supportFocus} onAct={act} />}
        {tab === "payments" && <PaymentAdmin providers={data.providers} payments={filtered.payments} refunds={filtered.refunds} events={data.paymentEvents} reconciliation={data.reconciliation} onAct={act} onRefund={setRefundPayment} />}
        {tab === "notifications" && <NotificationAdmin settings={data.notificationSettings} templates={data.notificationTemplates} jobs={filtered.notificationJobs} onAct={act} />}
        {tab === "members" && <section className="admin-panel"><div className="admin-panel-title"><h2>会员档案</h2><div className="admin-panel-actions"><span>{filtered.members.length} 位会员</span><ExportLink type="members" /></div></div><div className="admin-table-wrap"><table><thead><tr><th>会员</th><th>联系方式</th><th>订单</th><th>累计消费</th><th>加入时间</th><th>状态</th><th>详情</th></tr></thead><tbody>{filtered.members.map((member) => <tr key={member.id}><td><b>{member.name}</b><small>#{member.id}</small></td><td>{member.email}<small>{member.phone}</small></td><td>{member.total_orders}</td><td>{formatCnyFromRub(member.total_spent)}</td><td>{new Date(member.joined_at).toLocaleDateString("zh-CN")}</td><td><select value={member.status} disabled={!can("customers.manage")} onChange={(event) => act({ action:"update-member-status", id:member.id, status:event.target.value })}><option value="active">普通会员</option><option value="vip">VIP</option><option value="blocked">已停用</option></select></td><td><button className="admin-text-button" onClick={() => setSelectedMember(member)}>查看</button></td></tr>)}</tbody></table></div></section>}
        {tab === "products" && <ProductManagement products={data.products} categories={data.productCategories} query={query} canManage={can("products.manage")} canInventoryManage={can("products.inventory.manage")} onCreate={() => { setEditing(null); setCreating(true); }} onImport={() => setImporting(true)} onEdit={(product) => { setEditing(product); setCreating(false); }} onAct={act} />}
        {tab === "reviews" && <ReviewsAdmin reviews={filtered.reviews} onAct={act} />}
        {tab === "community" && <CommunityAdmin posts={filtered.communityPosts} canManage={can("community.manage")} onAct={act} />}
        {tab === "returns" && <section className="admin-panel"><div className="admin-panel-title"><h2>售后申请</h2><div className="admin-panel-actions"><span>{filtered.returns.length} 条申请</span><ExportLink type="returns" /></div></div><div className="admin-table-wrap"><table><thead><tr><th>售后单号</th><th>订单号</th><th>诉求 / 原因</th><th>退回物流</th><th>状态</th><th>售后处理</th><th>客户沟通</th></tr></thead><tbody>{filtered.returns.length ? filtered.returns.map((item) => <tr key={item.id}><td><b>{item.id}</b>{item.support_thread_id && <small>工单 {item.support_thread_id}</small>}</td><td>{item.order_id}<small>{item.email}</small></td><td>{item.request_type === "exchange" ? "换货" : item.request_type === "reship" ? "补寄" : "退货退款"}<small>{item.reason}{returnItemSummary(item.items_json) && <><br />商品：{returnItemSummary(item.items_json)}</>}<br />{item.details || "无补充说明"}</small></td><td>{item.return_tracking_number ? <>{item.return_carrier}<small>{item.return_tracking_number}</small></> : "尚未填写"}</td><td><PaymentStatus value={item.status} />{item.refund_id && <small>退款单 {item.refund_id}</small>}</td><td><select value={item.status} disabled={["退款中","已退款"].includes(item.status)} onChange={(event) => act({ action:"update-return-status", id:item.id, status:event.target.value })}>{["待审核","已批准","补发处理中","已拒绝","已关闭"].map((status) => <option key={status}>{status}</option>)}</select>{can("finance.manage") && item.request_type === "refund" && !item.refund_id && !["已拒绝","已关闭"].includes(item.status) && <button className="admin-text-button danger" onClick={() => { const amountYuan = window.prompt("退款金额（元）；留空则退剩余全部金额", ""); const reason = window.prompt("退款处理说明", "售后审核通过"); if (reason !== null) void act({ action: "approve-return-refund", id: item.id, amountYuan: amountYuan || undefined, reason }); }}>审核并退款</button>}</td><td><button className="admin-communication-button" onClick={() => void openLinkedSupport({ returnId: item.id })}>{item.support_thread_id ? "查看并回复" : "建立客服工单"}</button></td></tr>) : <tr><td className="admin-empty" colSpan={7}>暂无售后申请</td></tr>}</tbody></table></div></section>}
        {tab === "partnerships" && <section className="admin-panel"><div className="admin-panel-title"><div><h2>中国区零售合作申请</h2><p>集中处理官网提交的渠道、经销与企业采购咨询。</p></div><div className="admin-panel-actions"><span>{filtered.retailPartnerships.length} 条申请</span><ExportLink type="partnerships" /></div></div><div className="admin-table-wrap"><table><thead><tr><th>申请人 / 公司</th><th>联系方式</th><th>地区 / 类型</th><th>合作方案</th><th>提交时间</th><th>状态</th></tr></thead><tbody>{filtered.retailPartnerships.length ? filtered.retailPartnerships.map((item) => <tr key={item.id}><td><b>{item.contact_name}</b><small>{item.company}<br />{item.id}</small></td><td>{item.phone}<small>{item.wechat ? `微信：${item.wechat}` : "未填写微信"}<br />{item.email || "未填写邮箱"}</small></td><td>{item.city}<small>{item.cooperation_type}</small></td><td className="admin-partnership-proposal">{item.proposal}</td><td>{new Date(item.created_at).toLocaleString("zh-CN")}</td><td><select value={item.status} onChange={(event) => act({ action:"update-retail-partnership-status", id:item.id, status:event.target.value })}>{["待联系","洽谈中","已合作","已拒绝","已关闭"].map((status) => <option key={status}>{status}</option>)}</select></td></tr>) : <tr><td className="admin-empty" colSpan={6}>暂无零售合作申请</td></tr>}</tbody></table></div></section>}
        {tab === "marketing" && <div className="admin-marketing"><section className="admin-panel"><div className="admin-panel-title"><h2>优惠码</h2><span>{filtered.coupons.length} 个</span></div><form className="coupon-admin-form" onSubmit={saveCoupon}><input name="code" placeholder="优惠码，例如 SUMMER20" required /><select name="kind"><option value="percent">百分比</option><option value="fixed">固定金额（元）</option></select><input name="value" type="number" min="1" step="0.01" placeholder="折扣比例或金额" required /><input name="minimum" type="number" min="0" step="0.01" placeholder="最低消费（元）" /><input name="usageLimit" type="number" min="0" placeholder="限用次数，0不限" /><button>创建优惠码</button></form><div className="admin-table-wrap"><table><thead><tr><th>优惠码</th><th>方式</th><th>门槛</th><th>使用</th><th>状态</th></tr></thead><tbody>{filtered.coupons.map((coupon) => <tr key={coupon.id}><td><b>{coupon.code}</b></td><td>{coupon.kind === "percent" ? `${coupon.value}%` : formatCnyFromRub(coupon.value)}</td><td>{coupon.minimum ? formatCnyFromRub(coupon.minimum) : "无门槛"}</td><td>{coupon.used_count} / {coupon.usage_limit || "不限"}</td><td><select value={coupon.status} onChange={(event) => act({ action:"update-coupon-status", id:coupon.id, status:event.target.value })}><option value="active">启用</option><option value="disabled">停用</option></select></td></tr>)}</tbody></table></div></section><section className="admin-panel"><div className="admin-panel-title"><h2>礼品卡</h2><span>{filtered.giftCards.length} 张</span></div><div className="admin-table-wrap"><table><thead><tr><th>卡号</th><th>收件人</th><th>余额</th><th>来源订单</th><th>发送日期</th><th>状态</th></tr></thead><tbody>{filtered.giftCards.length ? filtered.giftCards.map((card) => <tr key={card.code}><td><b>{card.code}</b></td><td>{card.recipient_name}<small>{card.recipient_email}</small></td><td>{formatCnyFromRub(card.balance)}<small>初始 {formatCnyFromRub(card.initial_balance)}</small></td><td>{card.order_id}</td><td>{card.delivery_date || "立即"}</td><td><select value={card.status} onChange={(event) => act({ action:"update-gift-card-status", code:card.code, status:event.target.value })}><option value="active">有效</option><option value="used">已用完</option><option value="void">已作废</option></select></td></tr>) : <tr><td className="admin-empty" colSpan={6}>完成礼品卡订单后会在这里生成卡号</td></tr>}</tbody></table></div></section></div>}
        {tab === "subscribers" && <section className="admin-panel"><div className="admin-panel-title"><h2>邮件订阅名单</h2><div className="admin-panel-actions"><span>{filtered.subscribers.length} 位订阅用户</span><ExportLink type="subscribers" /></div></div><div className="admin-table-wrap"><table><thead><tr><th>邮箱</th><th>来源</th><th>订阅时间</th><th>状态</th></tr></thead><tbody>{filtered.subscribers.map((subscriber) => <tr key={subscriber.id}><td><b>{subscriber.email}</b></td><td>{subscriber.source === "homepage" ? "首页" : subscriber.source === "footer" ? "页脚" : subscriber.source}</td><td>{new Date(subscriber.subscribed_at).toLocaleString("zh-CN")}</td><td><select value={subscriber.status} onChange={(event) => act({ action:"update-subscriber-status", id:subscriber.id, status:event.target.value })}><option value="active">订阅中</option><option value="unsubscribed">已退订</option></select></td></tr>)}</tbody></table></div></section>}
        {tab === "admins" && <AdminUsersAdmin users={data.adminUsers} currentAdminId={viewer.id} onAct={act} />}
        {tab === "audit" && <AuditLogAdmin logs={data.auditLogs} />}
      </>}
    </section>
    {(creating || editing) && <ProductModal editing={editing} categories={data?.productCategories ?? []} inventoryOnly={Boolean(editing && !can("products.manage"))} onClose={() => { setCreating(false); setEditing(null); }} onSubmit={saveProduct} />}
    {importing && <ImportModal onClose={() => setImporting(false)} onImport={async (products) => { const ok = await act({ action: "bulk-import-products", products }); if (ok) setImporting(false); }} />}
    {selectedOrder && data && <OrderModal order={selectedOrder} items={data.orderItems.filter((item) => item.order_id === selectedOrder.id)} communicationCount={data.supportThreads.filter((thread) => thread.order_id === selectedOrder.id && !thread.deleted_at).length} canSupport={can("support.manage")} onSupport={() => void openLinkedSupport({ orderId: selectedOrder.id })} onClose={() => setSelectedOrder(null)} />}
    {selectedMember && data && <MemberModal member={selectedMember} orders={data.orders.filter((order) => order.member_id === selectedMember.id)} onClose={() => setSelectedMember(null)} />}
    {refundPayment && <RefundModal payment={refundPayment} onClose={() => setRefundPayment(null)} onSubmit={async (amountYuan, reason) => { const ok = await act({ action: "create-refund", paymentId: refundPayment.id, amountYuan, reason }); if (ok) setRefundPayment(null); }} />}
  </main>;
}

function ExportLink({ type }: { type: string }) { return <a className="admin-export" href={`/api/admin/export?type=${type}`}>导出 CSV</a>; }

function RevenueChart({ points }: { points: TrendPoint[] }) {
  const days = Array.from({ length: 30 }, (_, index) => { const date = new Date(); date.setDate(date.getDate() - 29 + index); return date.toISOString().slice(0, 10); });
  const values = days.map((day) => points.find((point) => point.day === day)?.revenue ?? 0);
  const max = Math.max(...values, 1);
  return <section className="admin-panel revenue-chart"><div className="admin-panel-title"><div><h2>近 30 天销售趋势</h2><p>按非取消订单统计</p></div><b>{formatCnyFromRub(values.reduce((sum, value) => sum + value, 0))}</b></div><div className="revenue-bars">{values.map((value, index) => <i key={days[index]} style={{ height: `${Math.max(3, value / max * 100)}%` }} title={`${days[index]} · ${formatCnyFromRub(value)}`} />)}</div><div className="revenue-axis"><span>{days[0].slice(5)}</span><span>{days[14].slice(5)}</span><span>{days[29].slice(5)}</span></div></section>;
}

function ImportModal({ onClose, onImport }: { onClose: () => void; onImport: (products: Record<string, unknown>[]) => Promise<void> }) {
  const [value, setValue] = useState('[\n  {\n    "name": "中文商品名称",\n    "category": "彩妆",\n    "price": 118.8,\n    "stock": 0,\n    "inventoryVerified": false,\n    "image": "/assets/01.webp"\n  }\n]');
  const [error, setError] = useState("");
  function parse() {
    setError("");
    try { const parsed = JSON.parse(value); if (!Array.isArray(parsed)) throw new Error("JSON 顶层必须是数组"); void onImport(parsed); return; } catch (jsonError) {
      try { const lines = value.trim().split(/\r?\n/).filter(Boolean); const headers = lines[0].split(",").map((item) => item.trim()); if (!headers.includes("name")) throw new Error("CSV 必须包含 name 列"); const rows = lines.slice(1).map((line) => Object.fromEntries(line.split(",").map((cell,index) => [headers[index], cell.trim()]))); void onImport(rows); } catch { setError(jsonError instanceof Error ? jsonError.message : "无法解析导入内容"); }
    }
  }
  return <div className="admin-modal" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className="admin-detail-card"><div className="admin-panel-title"><div><p>最多一次导入 200 件</p><h2>批量导入商品</h2></div><button onClick={onClose}>×</button></div><p className="admin-help">支持 JSON 数组或 CSV，商品链接由系统自动维护；price 与 oldPrice 均直接填写人民币元。category 必须使用“分类管理”中已启用的分类名称。</p><textarea className="admin-import-area" value={value} onChange={(event) => setValue(event.target.value)} rows={18} />{error && <p className="checkout-error">{error}</p>}<button className="admin-save" onClick={parse}>开始导入</button></section></div>;
}

function NotificationAdmin({ settings, templates, jobs, onAct }: { settings: NotificationSetting[]; templates: NotificationTemplate[]; jobs: NotificationJob[]; onAct: (payload: Record<string, unknown>) => Promise<boolean> }) {
  return <div className="admin-notification-stack">
    <section className="notification-settings-grid">{settings.map((setting) => <form className="notification-setting-card" key={setting.channel} onSubmit={(event) => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); void onAct({ action: "update-notification-setting", channel: setting.channel, enabled: values.enabled === "on", senderName: values.senderName, senderAddress: values.senderAddress }); }}><div className="payment-provider-title"><div><span>{setting.provider.toUpperCase()}</span><h2>{setting.display_name}</h2></div><label className="admin-switch"><input type="checkbox" name="enabled" defaultChecked={Boolean(setting.enabled)} /><i /></label></div><div className={`payment-config-state ${setting.configured ? "ready" : ""}`}><b>{setting.configured ? "配置完整，可发送通知" : "配置未完成，不会发送"}</b><span>服务器密钥 {setting.secretInstalled ? "已安装" : "未安装"}</span></div><label>发件名称<input name="senderName" defaultValue={setting.sender_name} /></label><label>{setting.channel === "email" ? "发件邮箱" : "短信签名 / Sender ID"}<input name="senderAddress" defaultValue={setting.sender_address} placeholder={setting.channel === "email" ? "notice@PUSY.CN" : "PUSY.CN"} /></label><p>{setting.channel === "email" ? "邮件通过 Resend 发送，API 密钥只保存在服务器环境变量。" : "短信通过独立 HTTP 网关适配器发送，可对接国内合规短信服务商。"}</p><button className="admin-save">保存渠道配置</button></form>)}</section>
    <section className="admin-panel"><div className="admin-panel-title"><div><h2>消息模板</h2><p>支持变量：订单号、客户、金额、配送、礼品卡代码等</p></div></div><div className="notification-template-list">{templates.map((template) => <details key={template.key}><summary><div><b>{template.name}</b><small>{template.key}</small></div><span>{template.enabled ? "已启用" : "已停用"} ＋</span></summary><form onSubmit={(event) => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); void onAct({ action: "update-notification-template", key: template.key, enabled: values.enabled === "on", emailSubject: values.emailSubject, emailBody: values.emailBody, smsBody: values.smsBody }); }}><label className="notification-template-toggle"><input type="checkbox" name="enabled" defaultChecked={Boolean(template.enabled)} /> 启用此模板</label><label>邮件标题<input name="emailSubject" defaultValue={template.email_subject} /></label><label>邮件正文<textarea name="emailBody" defaultValue={template.email_body} rows={7} /></label><label>短信正文<textarea name="smsBody" defaultValue={template.sms_body} rows={3} maxLength={500} /></label><button className="admin-save">保存模板</button></form></details>)}</div></section>
    <section className="admin-panel"><div className="admin-panel-title"><div><h2>发送记录</h2><p>{jobs.length} 条通知任务</p></div><button onClick={() => void onAct({ action: "process-notifications" })}>处理到期队列</button></div><div className="admin-table-wrap"><table><thead><tr><th>事件 / 接收人</th><th>渠道</th><th>模板</th><th>计划时间</th><th>状态</th><th>尝试</th><th>操作</th></tr></thead><tbody>{jobs.length ? jobs.map((job) => <tr key={job.id}><td><b>{job.entity_id}</b><small>{job.recipient}<br />{job.event_key}</small></td><td>{job.channel === "email" ? "邮件" : "短信"}</td><td>{templates.find((item) => item.key === job.template_key)?.name ?? job.template_key}</td><td>{new Date(job.scheduled_at).toLocaleString("zh-CN")}</td><td><NotificationStatus value={job.status} />{job.last_error && <small className="payment-row-error">{job.last_error}</small>}</td><td>{job.attempts}</td><td>{job.status !== "sent" && <button className="admin-text-button" onClick={() => void onAct({ action: "retry-notification", id: job.id })}>立即重试</button>}</td></tr>) : <tr><td colSpan={7} className="admin-empty">还没有消息通知记录</td></tr>}</tbody></table></div></section>
  </div>;
}

function NotificationStatus({ value }: { value: string }) { const labels: Record<string,string> = { queued: "待发送", failed: "发送失败", sent: "已发送", delivered: "已送达", bounced: "已退信", complained: "被投诉" }; return <span className={`payment-status status-${value}`}>{labels[value] ?? value}</span>; }

function ChinaRegionAdmin({ settings, providers, onOpenPayments }: { settings: ChinaRegionSettings; providers: PaymentProvider[]; onOpenPayments: () => void }) {
  const identityItems = [["中国区运营主体", settings.operatorName], ["统一社会信用代码", settings.unifiedSocialCreditCode], ["注册地址", settings.registeredAddress], ["客服电话", settings.customerServicePhone], ["客服邮箱", settings.supportEmail], ["隐私联系邮箱", settings.privacyEmail], ["ICP备案", settings.icpNumber], ["公安联网备案", settings.publicSecurityNumber]];
  const paymentsReady = providers.some((provider) => provider.enabled && provider.configured);
  return <div className="china-settings-stack">
    <section className="admin-panel china-readiness"><div className="admin-panel-title"><div><h2>中国区上线状态</h2><p>市场：中国大陆 · 语言：简体中文 · 时区：{settings.timeZone} · 货币：{settings.currency}</p></div><span className={`payment-status ${settings.complianceReady && paymentsReady ? "status-paid" : "status-pending"}`}>{settings.complianceReady && paymentsReady ? "基本配置完成" : "尚未满足上线条件"}</span></div><div className="china-check-grid"><article className={settings.complianceReady ? "ready" : "pending"}><b>{settings.complianceReady ? "✓" : "!"} 经营主体与备案</b><p>{settings.complianceReady ? "主体、联系方式与备案信息已配置。" : "仍有待补充信息，请通过服务器环境变量配置。"}</p></article><article className={paymentsReady ? "ready" : "pending"}><b>{paymentsReady ? "✓" : "!"} 中国区支付</b><p>{paymentsReady ? "至少一个支付渠道已启用并配置完整。" : "微信支付和支付宝均未达到可交易状态。"}</p></article><article className="ready"><b>✓ 中国区政策</b><p>隐私、Cookie、销售条款、配送和退换货页面已切换为中国区版本。</p></article></div></section>
    <section className="admin-panel"><div className="admin-panel-title"><div><h2>经营与备案信息</h2><p>以下内容会用于中国区法律公示；敏感配置不写入前端代码。</p></div><a href="/details" target="_blank" rel="noopener noreferrer">查看公示页</a></div><div className="china-settings-list">{identityItems.map(([label, value]) => <div key={label}><span>{label}</span><b className={value.startsWith("待") ? "pending" : ""}>{value}</b></div>)}</div><div className="admin-config-note"><b>配置方式</b><p>在运行环境中设置 CHINA_OPERATOR_NAME、CHINA_UNIFIED_SOCIAL_CREDIT_CODE、CHINA_REGISTERED_ADDRESS、CHINA_CUSTOMER_SERVICE_PHONE、CHINA_SUPPORT_EMAIL、CHINA_PRIVACY_EMAIL、CHINA_ICP_NUMBER 和 CHINA_PUBLIC_SECURITY_NUMBER。正式主体信息确认前不会用虚构资料填充。</p></div></section>
    <section className="admin-panel"><div className="admin-panel-title"><div><h2>支付渠道状态</h2><p>支付密钥由服务器环境管理，非管理员页面明文保存。</p></div><button onClick={onOpenPayments}>前往支付配置</button></div><div className="china-check-grid">{providers.map((provider) => <article className={provider.enabled && provider.configured ? "ready" : "pending"} key={provider.provider}><b>{provider.display_name}</b><p>{provider.enabled ? provider.configured ? "已启用，可发起真实交易。" : "已启用，但商户资料或服务器密钥不完整。" : "当前未启用。"}</p></article>)}</div></section>
  </div>;
}

function PaymentAdmin({ providers, payments, refunds, events, reconciliation, onAct, onRefund }: { providers: PaymentProvider[]; payments: AdminPayment[]; refunds: AdminRefund[]; events: PaymentEvent[]; reconciliation: Reconciliation; onAct: (payload: Record<string, unknown>) => Promise<boolean>; onRefund: (payment: AdminPayment) => void }) {
  return <div className="admin-payment-stack">
    <section className="admin-panel"><div className="admin-panel-title"><div><h2>支付与退款对账</h2><p>订单、支付、退款和库存确认状态自动交叉核验</p></div><div className="admin-panel-actions"><ExportLink type="payment-reconciliation" /><ExportLink type="refund-reconciliation" /></div></div><div className="stat-grid"><article><span>支付笔数</span><b>{reconciliation.summary.paymentCount}</b></article><article><span>收款金额</span><b>{(reconciliation.summary.paidFen / 100).toFixed(2)} 元</b></article><article><span>成功退款</span><b>{(reconciliation.summary.refundedFen / 100).toFixed(2)} 元</b></article><article><span>净收款</span><b>{(reconciliation.summary.netFen / 100).toFixed(2)} 元</b></article><article><span>异常项目</span><b>{reconciliation.summary.anomalyCount}</b></article></div>{reconciliation.items.some((item) => item.anomalies.length) ? <div className="admin-table-wrap"><table><thead><tr><th>订单 / 交易</th><th>渠道</th><th>支付</th><th>退款</th><th>净额</th><th>异常</th></tr></thead><tbody>{reconciliation.items.filter((item) => item.anomalies.length).map((item) => <tr key={item.payment_id}><td><b>{item.order_id}</b><small>{item.merchant_trade_no}</small></td><td>{item.provider === "wechat" ? "微信支付" : "支付宝"}</td><td>{(item.amount_fen / 100).toFixed(2)} 元<small>{item.payment_status}</small></td><td>{(item.succeeded_refund_fen / 100).toFixed(2)} 元</td><td>{(item.net_fen / 100).toFixed(2)} 元</td><td><span className="payment-row-error">{item.anomalies.join("；")}</span></td></tr>)}</tbody></table></div> : <p className="admin-empty">当前支付、退款、订单和库存确认数据一致。</p>}</section>
    <section className="payment-provider-grid">{providers.map((provider) => <form className="payment-provider-card" key={provider.provider} onSubmit={(event) => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); void onAct({ action: "update-payment-provider", provider: provider.provider, enabled: values.enabled === "on", mode: values.mode, appId: values.appId, merchantId: values.merchantId, publicKeyId: values.publicKeyId, certificateSerial: values.certificateSerial }); }}>
      <div className="payment-provider-title"><div><span>{provider.provider === "wechat" ? "WECHAT PAY" : "ALIPAY"}</span><h2>{provider.display_name}</h2></div><label className="admin-switch"><input type="checkbox" name="enabled" defaultChecked={Boolean(provider.enabled)} /><i /></label></div>
      <div className={`payment-config-state ${provider.configured ? "ready" : ""}`}><b>{provider.configured ? "配置完整，可发起真实交易" : "配置未完成，前台不会扣款"}</b><span>私钥 {provider.secrets.privateKey ? "已安装" : "未安装"} · 公钥 {provider.secrets.publicKey ? "已安装" : "未安装"}{provider.provider === "wechat" ? ` · API v3 密钥 ${provider.secrets.apiV3Key ? "已安装" : "未安装"}` : ""}</span>{provider.missing.length > 0 && <small>还缺：{provider.missing.join("、")}</small>}</div>
      <div className="payment-provider-form"><label>运行环境<select name="mode" defaultValue={provider.mode}><option value="production">正式环境</option>{provider.provider === "alipay" && <option value="sandbox">沙箱环境</option>}</select></label><label>应用 ID<input name="appId" defaultValue={provider.app_id} autoComplete="off" /></label><label>商户号<input name="merchantId" defaultValue={provider.merchant_id} autoComplete="off" /></label>{provider.provider === "wechat" && <><label>平台公钥 ID<input name="publicKeyId" defaultValue={provider.public_key_id} autoComplete="off" /></label><label>商户证书序列号<input name="certificateSerial" defaultValue={provider.certificate_serial} autoComplete="off" /></label></>}</div>
      <p>私钥、公钥和 API v3 密钥仅通过服务器环境变量配置，后台不会保存或回显。支付回调：https://pusy.cn/api/payments/webhooks/{provider.provider}{provider.provider === "wechat" ? "；退款回调：https://pusy.cn/api/payments/webhooks/wechat/refund" : ""}</p><button className="admin-save">保存渠道配置</button>
    </form>)}</section>
    <section className="admin-panel"><div className="admin-panel-title"><div><h2>支付交易</h2><p>{payments.length} 笔记录</p></div></div><div className="admin-table-wrap"><table><thead><tr><th>订单 / 客户</th><th>渠道</th><th>金额</th><th>支付状态</th><th>尝试</th><th>更新时间</th><th>操作</th></tr></thead><tbody>{payments.length ? payments.map((payment) => <tr key={payment.id}><td><b>{payment.order_id}</b><small>{payment.customer} · {payment.email}<br />{payment.merchant_trade_no}</small></td><td>{payment.provider === "wechat" ? "微信支付" : "支付宝"}</td><td>{(payment.amount_fen / 100).toFixed(2)} 元</td><td><PaymentStatus value={payment.status} />{payment.last_error && <small className="payment-row-error">{payment.last_error}</small>}</td><td>{payment.attempts}</td><td>{new Date(payment.updated_at).toLocaleString("zh-CN")}</td><td><button className="admin-text-button" onClick={() => void onAct({ action: "sync-payment", id: payment.id })}>同步</button>{payment.status === "failed" && <button className="admin-text-button" onClick={() => void onAct({ action: "retry-payment", orderId: payment.order_id, provider: payment.provider })}>重试</button>}{["paid","partially_refunded"].includes(payment.status) && <button className="admin-text-button danger" onClick={() => onRefund(payment)}>退款</button>}</td></tr>) : <tr><td colSpan={7} className="admin-empty">还没有支付交易</td></tr>}</tbody></table></div></section>
    <section className="admin-panel"><div className="admin-panel-title"><div><h2>退款记录</h2><p>{refunds.length} 笔记录</p></div></div><div className="admin-table-wrap"><table><thead><tr><th>退款单 / 订单</th><th>渠道</th><th>金额</th><th>原因</th><th>状态</th><th>操作</th></tr></thead><tbody>{refunds.length ? refunds.map((refund) => <tr key={refund.id}><td><b>{refund.id}</b><small>{refund.order_id}<br />{refund.merchant_refund_no}</small></td><td>{refund.provider === "wechat" ? "微信支付" : "支付宝"}</td><td>{(refund.amount_fen / 100).toFixed(2)} 元</td><td>{refund.reason}{refund.last_error && <small className="payment-row-error">{refund.last_error}</small>}</td><td><PaymentStatus value={refund.status} /></td><td><button className="admin-text-button" onClick={() => void onAct({ action: "sync-refund", id: refund.id })}>同步</button>{refund.status === "failed" && <button className="admin-text-button" onClick={() => void onAct({ action: "retry-refund", id: refund.id })}>重试</button>}</td></tr>) : <tr><td colSpan={6} className="admin-empty">还没有退款记录</td></tr>}</tbody></table></div></section>
    <section className="admin-panel"><div className="admin-panel-title"><div><h2>回调审计</h2><p>最近 {events.length} 条已验签事件</p></div></div><div className="payment-event-list">{events.length ? events.map((event) => <article key={event.id}><div><b>{event.provider === "wechat" ? "微信支付" : "支付宝"} · {event.event_type}</b><small>{event.id}</small></div><PaymentStatus value={event.result} /><time>{new Date(event.created_at).toLocaleString("zh-CN")}</time>{event.message && <p>{event.message}</p>}</article>) : <p className="admin-empty">尚未收到支付回调</p>}</div></section>
  </div>;
}

function PaymentStatus({ value }: { value: string }) {
  const labels: Record<string, string> = { created: "已创建", pending: "待支付", paid: "已支付", failed: "失败", closed: "已关闭", refunding: "退款中", partially_refunded: "部分退款", refunded: "已退款", processing: "处理中", succeeded: "成功", processed: "已处理", rejected: "已拒绝", ignored: "已忽略" };
  return <span className={`payment-status status-${value}`}>{labels[value] ?? value}</span>;
}

function RefundModal({ payment, onClose, onSubmit }: { payment: AdminPayment; onClose: () => void; onSubmit: (amountYuan: number, reason: string) => Promise<void> }) {
  const [busy, setBusy] = useState(false);
  return <div className="admin-modal" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><form onSubmit={async (event) => { event.preventDefault(); setBusy(true); const values = new FormData(event.currentTarget); await onSubmit(Number(values.get("amountYuan")), String(values.get("reason") ?? "")); setBusy(false); }}><div className="admin-panel-title"><div><p>订单 {payment.order_id}</p><h2>发起退款</h2></div><button type="button" onClick={onClose}>×</button></div><p className="admin-help">原支付金额 {(payment.amount_fen / 100).toFixed(2)} 元。系统会校验累计可退余额，并使用固定退款单号安全重试。</p><div className="admin-form-grid"><label>退款金额（元）<input name="amountYuan" type="number" min="0.01" max={(payment.amount_fen / 100).toFixed(2)} step="0.01" required /></label><label>退款原因<input name="reason" maxLength={80} required placeholder="例如：客户取消订单" /></label></div><button className="admin-save" disabled={busy}>{busy ? "正在提交退款…" : "确认发起退款"}</button></form></div>;
}

function orderStatusOptions(status: string, canFullManage = true) {
  if (!canFullManage) return [status, ...(["配货中", "已发货", "已完成"].includes(status) ? ["配货中", "已发货", "已完成"] : [])].filter((value, index, values) => values.indexOf(value) === index);
  if (["待付款", "支付失败", "待处理"].includes(status)) return [status, "已取消"];
  if (["已确认", "配货中"].includes(status)) return [status, "配货中"].filter((value, index, values) => values.indexOf(value) === index);
  if (status === "已发货") return ["已发货", "已完成"];
  if (status === "部分退款") return ["部分退款", "配货中", "已发货", "已完成"];
  return [status];
}

function OrderManagement({ orders, shipments, shipmentEvents, canManage, canFullManage, canSupport, onStatus, onOpen, onSupport, onAct }: { orders: AdminOrder[]; shipments: Shipment[]; shipmentEvents: ShipmentEvent[]; canManage: boolean; canFullManage: boolean; canSupport: boolean; onStatus: (id:string,status:string) => void; onOpen: (order:AdminOrder) => void; onSupport: (orderId: string) => void; onAct: (payload: Record<string, unknown>) => Promise<boolean> }) {
  const [selected, setSelected] = useState<string[]>([]);
  const [bulkStatus, setBulkStatus] = useState("配货中");
  const visibleSelected = selected.filter((id) => orders.some((order) => order.id === id));
  async function applyBulkStatus() {
    if (!visibleSelected.length) return;
    if (await onAct({ action: "bulk-update-order-status", ids: visibleSelected, status: bulkStatus })) setSelected([]);
  }
  const awaitingShipment = orders.filter((order) => order.has_physical_items && ["已确认", "配货中", "部分退款"].includes(order.status) && !shipments.some((shipment) => shipment.order_id === order.id));
  return <div className="admin-payment-stack"><section className="admin-panel"><div className="admin-panel-title"><div><h2>全部订单</h2><p>批量处理仅适用于已付款且已确认资源的订单；发货必须逐单登记物流。</p></div><div className="admin-panel-actions"><span>{orders.length} 条记录</span><ExportLink type="orders" /></div></div>{canManage && <div className="admin-bulk-toolbar"><b>已选 {visibleSelected.length} 个订单</b><select value={bulkStatus} onChange={(event) => setBulkStatus(event.target.value)}><option>配货中</option><option>已完成</option></select><button disabled={!visibleSelected.length} onClick={() => void applyBulkStatus()}>批量更新</button>{Boolean(visibleSelected.length) && <button className="secondary" onClick={() => setSelected([])}>取消选择</button>}</div>}<OrderTable orders={orders} canManage={canManage} canFullManage={canFullManage} canSupport={canSupport} selectedIds={canManage ? visibleSelected : undefined} onToggle={(id) => setSelected((current) => current.includes(id) ? current.filter((value) => value !== id) : [...current, id])} onToggleAll={() => setSelected(visibleSelected.length === orders.length ? [] : orders.map((order) => order.id))} onOpen={onOpen} onSupport={onSupport} onStatus={onStatus} /></section>{canManage && <section className="admin-panel"><div className="admin-panel-title"><div><h2>发货与物流</h2><p>{awaitingShipment.length} 笔待登记运单</p></div></div><div className="shipment-admin-list">{awaitingShipment.map((order) => <form key={order.id} onSubmit={(event) => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); void onAct({ action: "ship-order", orderId: order.id, carrierCode: values.carrierCode, trackingNumber: values.trackingNumber }); }}><b>{order.id}</b><span>{order.customer}</span><select name="carrierCode" defaultValue="sf"><option value="sf">顺丰速运</option><option value="jd">京东物流</option><option value="zto">中通快递</option><option value="yto">圆通速递</option><option value="sto">申通快递</option><option value="yunda">韵达快递</option><option value="ems">中国邮政 EMS</option><option value="other">其他物流</option></select><input name="trackingNumber" placeholder="物流单号" required maxLength={64} /><button>确认发货</button></form>)}</div>{shipments.length > 0 && <div className="admin-table-wrap"><table><thead><tr><th>订单 / 运单</th><th>承运商</th><th>状态</th><th>轨迹更新</th></tr></thead><tbody>{shipments.map((shipment) => <tr key={shipment.id}><td><b>{shipment.order_id}</b><small>{shipment.tracking_number}</small></td><td>{shipment.carrier_name}{shipment.tracking_url && <small><a href={shipment.tracking_url} target="_blank" rel="noopener noreferrer">承运商查询</a></small>}</td><td>{shipment.status}<small>{shipmentEvents.find((event) => event.shipment_id === shipment.id)?.description}</small></td><td><form onSubmit={(event) => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); void onAct({ action: "add-shipment-event", shipmentId: shipment.id, status: values.status, description: values.description, location: values.location }); }}><select name="status"><option>运输中</option><option>派送中</option><option>已签收</option><option>异常</option></select><input name="description" placeholder="轨迹说明" required /><input name="location" placeholder="地点（选填）" /><button>更新</button></form></td></tr>)}</tbody></table></div>}</section>}</div>;
}

function OrderTable({ orders, canManage, canFullManage = true, canSupport, selectedIds, onToggle, onToggleAll, onStatus, onOpen, onSupport }: { orders: AdminOrder[]; canManage: boolean; canFullManage?: boolean; canSupport: boolean; selectedIds?: string[]; onToggle?: (id: string) => void; onToggleAll?: () => void; onStatus: (id:string,status:string) => void; onOpen: (order:AdminOrder) => void; onSupport: (orderId: string) => void }) {
  const selectable = Boolean(selectedIds && onToggle && onToggleAll);
  return <div className="admin-table-wrap"><table><thead><tr>{selectable && <th><input type="checkbox" aria-label="选择当前全部订单" checked={Boolean(orders.length) && selectedIds?.length === orders.length} onChange={onToggleAll} /></th>}<th>订单号</th><th>客户</th><th>商品</th><th>金额</th><th>配送 / 支付</th><th>时间</th><th>状态</th>{canSupport && <th>邮件</th>}</tr></thead><tbody>{orders.length ? orders.map((order) => <tr key={order.id}>{selectable && <td><input type="checkbox" aria-label={`选择订单 ${order.id}`} checked={selectedIds?.includes(order.id)} onChange={() => onToggle?.(order.id)} /></td>}<td><button className="admin-order-link" onClick={() => onOpen(order)}>{order.id}</button></td><td>{order.customer}<small>{order.email}<br />{order.phone}</small></td><td>{order.item_count} 件</td><td>{formatCnyFromRub(order.total)}</td><td>{order.delivery}<small>{order.payment}</small></td><td>{new Date(order.created_at).toLocaleString("zh-CN")}</td><td><select value={order.status} disabled={!canManage || orderStatusOptions(order.status, canFullManage).length < 2} onChange={(event) => onStatus(order.id,event.target.value)}>{orderStatusOptions(order.status, canFullManage).map((status) => <option value={status} key={status}>{status}</option>)}</select></td>{canSupport && <td><button className="admin-communication-button" onClick={() => onSupport(order.id)}>联系客户</button></td>}</tr>) : <tr><td colSpan={(selectable ? 1 : 0) + (canSupport ? 8 : 7)} className="admin-empty">还没有符合条件的订单</td></tr>}</tbody></table></div>;
}

function ProductModal({ editing, categories, inventoryOnly, onClose, onSubmit }: { editing: AdminProduct | null; categories: ProductCategory[]; inventoryOnly: boolean; onClose: () => void; onSubmit: (event:React.FormEvent<HTMLFormElement>) => void }) {
  const categoryId = editing?.category_id ?? categories.find((category) => category.name === editing?.category)?.id ?? categories.find((category) => category.status === "active")?.id ?? "";
  return <div className="admin-modal" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><form onSubmit={onSubmit}><div className="admin-panel-title"><h2>{inventoryOnly ? `更新库存 · ${editing?.name}` : editing ? "编辑商品" : "新建商品"}</h2><button type="button" onClick={onClose}>×</button></div><div className="admin-form-grid">{!inventoryOnly && <><label>商品名称<input name="name" defaultValue={editing?.name ?? emptyProduct.name} required /></label><label>分类<select name="categoryId" defaultValue={categoryId} required><option value="" disabled>请选择分类</option>{categories.filter((category) => category.status === "active" || category.id === categoryId).map((category) => <option value={category.id} key={category.id}>{category.parent_name ? `${category.parent_name} / ` : ""}{category.name}{category.status === "disabled" ? "（已停用）" : ""}</option>)}</select></label><label>角标<input name="badge" defaultValue={editing?.badge ?? emptyProduct.badge} /></label><label>售价（元）<input name="price" type="number" min="0" step="0.01" defaultValue={storedToYuan(editing?.price)} required /></label><label>原价（元）<input name="oldPrice" type="number" min="0" step="0.01" defaultValue={storedToYuan(editing?.old_price)} /></label></>}<label>库存数量<input name="stock" type="number" min="0" defaultValue={editing?.stock ?? emptyProduct.stock} required /></label><label>低库存预警值<input name="lowStockThreshold" type="number" min="0" defaultValue={editing?.low_stock_threshold ?? emptyProduct.low_stock_threshold} required /></label><label className="inventory-check"><input name="inventoryVerified" type="checkbox" defaultChecked={Boolean(editing?.inventory_verified)} />库存数量已核验</label>{!inventoryOnly && <><label>状态<select name="status" defaultValue={editing?.status ?? emptyProduct.status}><option value="active">销售中</option><option value="archived">已下架</option></select></label><label>商品编号 / SKU<input name="sku" defaultValue={editing?.sku ?? emptyProduct.sku} /></label><label>规格容量<input name="volume" defaultValue={editing?.volume ?? emptyProduct.volume} placeholder="例如：110 毫升" /></label><label className="full">主图地址<input name="image" defaultValue={editing?.image ?? emptyProduct.image} required /></label><label className="full">备用图片地址<input name="imageAlt" defaultValue={editing?.image_alt ?? emptyProduct.image_alt} /></label><label className="full">商品说明<textarea name="description" defaultValue={editing?.description ?? emptyProduct.description} rows={4} /></label><label className="full">成分<textarea name="ingredients" defaultValue={editing?.ingredients ?? emptyProduct.ingredients} rows={4} /></label><label className="full">使用方法<textarea name="usage" defaultValue={editing?.usage ?? emptyProduct.usage} rows={4} /></label></>}</div>{editing && !editing.inventory_verified && <p className="inventory-source-note">请填写本商城的实际库存数量，确认无误后勾选“库存数量已核验”。</p>}<button className="admin-save">{inventoryOnly ? "保存库存" : "保存商品"}</button></form></div>;
}

function OrderModal({ order, items, communicationCount, canSupport, onSupport, onClose }: { order: AdminOrder; items: OrderItem[]; communicationCount: number; canSupport: boolean; onSupport: () => void; onClose: () => void }) { return <div className="admin-modal" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className="admin-detail-card"><div className="admin-panel-title"><div><p>订单详情</p><h2>{order.id}</h2></div><button onClick={onClose}>×</button></div><div className="admin-detail-grid"><article><span>客户</span><b>{order.customer}</b><p>{order.email}<br />{order.phone}</p></article><article><span>配送</span><b>{order.delivery}</b><p>{order.address}</p></article><article><span>支付</span><b>{order.payment}</b><p>{order.status}</p></article></div>{canSupport && <div className="admin-order-contact"><div><b>客户邮件沟通</b><p>{communicationCount ? `已有 ${communicationCount} 个关联工单，回复会自动带上订单号。` : "尚无关联邮件，打开后会建立订单工单。"}</p></div><button onClick={onSupport}>{communicationCount ? "查看并回复邮件" : "邮件联系客户"}</button></div>}<h3>商品明细</h3><div className="admin-order-items">{items.map((item) => <div key={item.id}><span>{item.product_name}<small>{item.product_slug}</small></span><b>× {item.quantity}</b><strong>{formatCnyFromRub(item.unit_price * item.quantity)}</strong></div>)}</div><div className="admin-detail-total"><span>订单合计</span><b>{formatCnyFromRub(order.total)}</b></div></section></div>; }

function MemberModal({ member, orders, onClose }: { member: AdminMember; orders: AdminOrder[]; onClose: () => void }) { return <div className="admin-modal" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className="admin-detail-card"><div className="admin-panel-title"><div><p>会员档案 #{member.id}</p><h2>{member.name}</h2></div><button onClick={onClose}>×</button></div><div className="admin-detail-grid"><article><span>联系方式</span><b>{member.email}</b><p>{member.phone}</p></article><article><span>累计订单</span><b>{member.total_orders} 笔</b><p>{formatCnyFromRub(member.total_spent)}</p></article><article><span>会员状态</span><b>{member.status === "vip" ? "VIP" : member.status === "blocked" ? "已停用" : "普通会员"}</b><p>加入于 {new Date(member.joined_at).toLocaleDateString("zh-CN")}</p></article></div><h3>订单历史</h3><div className="admin-member-orders">{orders.length ? orders.map((order) => <div key={order.id}><b>{order.id}</b><span>{new Date(order.created_at).toLocaleDateString("zh-CN")}</span><span>{order.status}</span><strong>{formatCnyFromRub(order.total)}</strong></div>) : <p>暂无订单</p>}</div></section></div>; }
